    const addTopFloorBtn = document.createElement("button");
    addTopFloorBtn.className = "add-floor-btn";
    addTopFloorBtn.textContent = "\u2795 \u65B0\u5EFA\u697C\u5C42\uFF08\u5411\u4E0A\u6269\u5C55\uFF09";
