          analyzeAllBtn: iframeDoc.getElementById("analyzeAllBtn"),
          logList: iframeDoc.getElementById("logList"),
          profileModal: iframeDoc.getElementById("profileModal"),
          profileTitle: iframeDoc.getElementById("profileTitle"),
