      setNotice(`${proposal.person.name}\u5DF2\u7ECF\u5F00\u59CB\u81EA\u5DF1\u7684\u751F\u6D3B\u884C\u52A8\uFF1B\u4EBA\u7269\u4F4D\u7F6E\u4E0E\u7A7A\u95F4\u5360\u7528\u5DF2\u540C\u6B65\u3002`, "success");
